#pragma once
#include <string>

namespace blitz::format {
	/** Which one-line Ifs (If a Then b Else c) become an If block. */
	enum class split_if {
		never,
		incompatible, // Only those that the original rejects: a call with its arguments in parentheses right before Else.
		always,
	};

	/** Turn the one-line Ifs of the source into If blocks (If a Then / b / Else / c / EndIf), as the mode says. A one-line If
	 * without Then, or with ElseIf or EndIf on its line, is left alone. The indentation is left to the formatter.
	 */
	std::string split_one_line_ifs(std::string const& source, split_if mode);
} // namespace blitz::format
